def ensure(ch):
    p=os.path.join(K,'%05x.svg'%ord(ch))
    if not os.path.exists(p):
        import urllib.request
        try: urllib.request.urlretrieve('https://raw.githubusercontent.com/KanjiVG/kanjivg/master/kanji/%05x.svg'%ord(ch),p)
        except Exception: pass
    return os.path.exists(p)
def strokes(ch):
    if not ensure(ch): return []
    s=open(os.path.join(K,'%05x.svg'%ord(ch)),encoding='utf-8').read()
    out=[]
    for tag in re.findall(r'<path [^>]*>',s):
        m=re.search(r'id="kvg:[0-9a-f]+-s(\d+)"',tag); d=re.search(r' d="([^"]+)"',tag)
        if m and d: out.append((int(m.group(1)),d.group(1)))
    return [d for _,d in sorted(out)]
