import glob,sys,re
sys.path.insert(0,os.path.dirname(__file__))
from parse import parse_file
import xml.etree.ElementTree as ET
def autopg(ch):
    try:
        t=ET.parse(os.path.join(K,'%05x.svg'%ord(ch)));KV='{http://kanjivg.tagaini.net}'
        root=[g for g in t.iter('{http://www.w3.org/2000/svg}g') if g.get('id','').startswith('kvg:StrokePaths')][0][0]
        out=[]
        for c in root:
            ids=[int(re.search(r's(\d+)$',p.get('id')).group(1)) for p in c.iter('{http://www.w3.org/2000/svg}path')]
            if not ids: continue
            lab=c.get(KV+'element') or ''
            if out and not lab and not out[-1][0]: out[-1][2]=max(ids);continue
            out.append([lab,min(ids),max(ids)])
        for o in out:
            if not o[0]: o[0]='·'
        return out if len(out)>1 else [[ch,1,len(strokes(ch))]]
    except Exception: return [[ch,1,1]]
files=sorted(glob.glob(os.path.join(REPO,'content','works','kanji-*.md')),key=lambda f:re.search(r'^date: (.*)$',open(f,encoding='utf-8').read(),re.M).group(1))
